import { Logger } from "trm-commons";
import { TARSYSTEM } from "../../../client";
import { SystemConnector } from "../../../systemConnector";
import { setTransportTarget } from "./setTransportTarget";

/**
 * Resolves the target system of the transports of copies generated by publish.
 *
 * Publish only creates and releases the transports: it never forwards or imports them, so the
 * target is not required to be a real route. When the connected system has no transport
 * targets, the system itself is used as target.
 *
 * @param noInquirer Disable interactive target selection.
 * @param userInput Explicit target to validate and use.
 * @param inquirerMessage Prompt label used when interactive selection is required.
 * @returns The selected, valid transport target.
 */
export async function setPublishTarget(noInquirer: boolean, userInput: TARSYSTEM | undefined, inquirerMessage: string): Promise<TARSYSTEM> {
    Logger.loading(`Checking system target...`);
    var transportTargets = await SystemConnector.getTransportTargets();
    if (transportTargets.length === 0) {
        //no transport targets: the transports of copies target the system itself
        const dest = SystemConnector.getDest();
        Logger.info(`No transport targets in ${dest}, using ${dest} itself as target`);
        transportTargets = [dest];
    }
    return setTransportTarget(noInquirer, transportTargets, userInput, inquirerMessage);
}
